<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';
require_permission('staff.kyc');
$uploadRoot=APP_ROOT.'/uploads/staff'; if(!is_dir($uploadRoot))mkdir($uploadRoot,0700,true);
if(is_post()){verify_csrf();try{$adminId=(int)input('admin_id');$mobile=trim((string)input('mobile'));if(!preg_match('/^[0-9+() -]{7,30}$/',$mobile))throw new InvalidArgumentException('A valid mobile number is required.');$stmt=db()->prepare('SELECT id FROM admins WHERE id=?');$stmt->execute([$adminId]);if(!$stmt->fetch())throw new InvalidArgumentException('Administrator not found.');$paths=[];foreach(['aadhaar_front','aadhaar_back','pan','photo'] as $field){if(empty($_FILES[$field]['tmp_name']))continue;$file=$_FILES[$field];if($file['error']!==UPLOAD_ERR_OK||$file['size']>5*1024*1024)throw new InvalidArgumentException('Each upload must be under 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))throw new InvalidArgumentException('Only JPG, PNG, or PDF files are accepted.');$name=bin2hex(random_bytes(20)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$uploadRoot.'/'.$name))throw new RuntimeException('Could not store upload.');$paths[$field]=$name;}$base=[$adminId,$mobile,trim((string)input('address')),trim((string)input('designation'))];$columns=['admin_id','mobile','address','designation'];$values=['?','?','?','?'];foreach($paths as $field=>$path){$columns[]=$field.'_path';$values[]='?';$base[]=$path;}$columns[]='kyc_status';$values[]='"PENDING"';$updates=['mobile=VALUES(mobile)','address=VALUES(address)','designation=VALUES(designation)','kyc_status="PENDING"'];foreach(array_keys($paths) as $field)$updates[]=$field.'_path=VALUES('.$field.'_path)';$sql='INSERT INTO staff_profiles('.implode(',',$columns).') VALUES('.implode(',',$values).') ON DUPLICATE KEY UPDATE '.implode(',',$updates);$pdo=db();$pdo->prepare($sql)->execute($base);audit_log((int)admin()['id'],'STAFF_KYC_SUBMITTED','staff_profiles',(string)$adminId);flash('success','Staff KYC profile saved for review.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/admins/staff.php');}
$admins=db()->query('SELECT a.id,a.name,a.username,s.mobile,s.designation,s.kyc_status FROM admins a LEFT JOIN staff_profiles s ON s.admin_id=a.id ORDER BY a.id')->fetchAll();$pageTitle='Staff KYC & OTP';$pageSubtitle='KYC-gated staff profiles and permission-ready administration';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><h2>Staff KYC profile</h2><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><div class="field"><label>Administrator</label><select name="admin_id" required><?php foreach($admins as $a):?><option value="<?=e($a['id'])?>"><?=e($a['name'].' · '.$a['username'])?></option><?php endforeach?></select></div><div class="field"><label>Registered mobile</label><input name="mobile" required></div><div class="field"><label>Designation</label><input name="designation" maxlength="120"></div><div class="field full"><label>Residential address</label><textarea name="address" maxlength="500"></textarea></div><?php foreach(['aadhaar_front'=>'Aadhaar front','aadhaar_back'=>'Aadhaar back','pan'=>'PAN document','photo'=>'Profile/live photo'] as $name=>$label):?><div class="field"><label><?=e($label)?></label><input type="file" name="<?=e($name)?>" accept="image/jpeg,image/png,application/pdf"></div><?php endforeach?><div class="field full"><button class="btn">Save KYC profile</button></div></form></section><section class="panel"><h2>Staff records</h2><div class="table-wrap"><table><thead><tr><th>Staff</th><th>Mobile</th><th>Designation</th><th>KYC</th></tr></thead><tbody><?php foreach($admins as $a):?><tr><td><?=e($a['name'])?><br><small><?=e($a['username'])?></small></td><td><?=e($a['mobile']??'—')?></td><td><?=e($a['designation']??'—')?></td><td><?=e($a['kyc_status']??'PENDING')?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
